import{_ as a,o as e,c as r,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const b=JSON.parse('{"title":"实时互动","description":"","frontmatter":{},"headers":[],"relativePath":"features/interaction.md","filePath":"features/interaction.md","lastUpdated":1786210541000}'),l={name:"features/interaction.md"};function i(d,t,n,h,s,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="实时互动" tabindex="-1">实时互动 <a class="header-anchor" href="#实时互动" aria-label="Permalink to &quot;实时互动&quot;">​</a></h1><h2 id="功能概述" tabindex="-1">功能概述 <a class="header-anchor" href="#功能概述" aria-label="Permalink to &quot;功能概述&quot;">​</a></h2><p>在 ZViewer 房间里，你和好友不仅可以同步看视频，还能实时互动——发弹幕、聊天、语音、甚至用画笔在画面上圈画。</p><hr><h2 id="一、评论与聊天" tabindex="-1">一、评论与聊天 <a class="header-anchor" href="#一、评论与聊天" aria-label="Permalink to &quot;一、评论与聊天&quot;">​</a></h2><p>评论面板在房间界面的<strong>右侧面板</strong>（CommentPanel），包含三个 Tab。</p><h3 id="如何发送评论" tabindex="-1">如何发送评论 <a class="header-anchor" href="#如何发送评论" aria-label="Permalink to &quot;如何发送评论&quot;">​</a></h3><ol><li>确保处于 <strong>「评论区」Tab</strong></li><li>在底部的输入框中输入文字</li><li>按回车或点击发送按钮</li><li>评论会立即显示，房间内所有人都能看到</li></ol><h2 id="二、观众申请控制" tabindex="-1">二、观众申请控制 <a class="header-anchor" href="#二、观众申请控制" aria-label="Permalink to &quot;二、观众申请控制&quot;">​</a></h2><p>作为观众，如果你想快进/后退或暂停，可以向房主发送申请。</p><ol><li>在播放器上点击暂停/跳转进度</li><li>系统提示&quot;已向房主发送申请，请等待确认&quot;</li><li>房主的播放器左上角显示通知</li><li>房主点击同意或拒绝</li></ol><p>如果房主开启了 <strong>「自动通过控制请求」</strong>，申请会自动生效。</p><h2 id="三、语音聊天" tabindex="-1">三、语音聊天 <a class="header-anchor" href="#三、语音聊天" aria-label="Permalink to &quot;三、语音聊天&quot;">​</a></h2><p>语音面板（VoiceChatPanel）常驻在页面<strong>右下角</strong>。</p><h3 id="房主开启语音" tabindex="-1">房主开启语音 <a class="header-anchor" href="#房主开启语音" aria-label="Permalink to &quot;房主开启语音&quot;">​</a></h3><ol><li>点击右下角语音面板</li><li>开启语音</li><li>设置比特率：32 / 96 / 128 / 192 kbps（默认 128 kbps）</li><li>开启后观众可收听</li></ol><blockquote><p>语音采用<strong>服务器中转模式</strong>（而非 P2P），以解决当前 NAT 环境下 P2P 封锁导致的无法语音聊天问题。中转模式下音频流经服务器转发，兼容性更好，不受 NAT 类型限制。</p><p>播放链路内置<strong>自适应 jitter buffer</strong>，根据网络抖动自动调整缓冲，降低卡顿与延迟；编解码链路锁定采样率并提供解码兜底，开麦首句听感更自然。</p></blockquote><h3 id="成员身份与显示" tabindex="-1">成员身份与显示 <a class="header-anchor" href="#成员身份与显示" aria-label="Permalink to &quot;成员身份与显示&quot;">​</a></h3><ul><li>语音成员绑定<strong>真实身份</strong>（登录用户显示用户名，游客显示昵称），不再以 socketId 前缀充当显示名。</li><li>同一登录用户断线重连会<strong>自动顶替</strong>旧条目，从根源消除&quot;3 人语音显示 8 人&quot;的幽灵残留。</li><li>语音面板中会显示成员列表，可调节扬声器音量。</li></ul><h3 id="语音管理-房主-房管" tabindex="-1">语音管理（房主 / 房管） <a class="header-anchor" href="#语音管理-房主-房管" aria-label="Permalink to &quot;语音管理（房主 / 房管）&quot;">​</a></h3><p>房主或房管可对语音成员执行：</p><ul><li><strong>语音禁言 / 解禁</strong>：禁言期间服务器中转层直接丢弃该成员的音频包（服务器侧强制，客户端无法绕过），被禁言者仍可收听。</li><li><strong>移出语音</strong>：将被移出的成员踢出语音频道（60 秒冷却期内无法重新加入）。</li></ul><h2 id="四、房管角色" tabindex="-1">四、房管角色 <a class="header-anchor" href="#四、房管角色" aria-label="Permalink to &quot;四、房管角色&quot;">​</a></h2><p>房主可以在<strong>观众管理</strong>中任命登录用户为<strong>房管</strong>（协管员），上限 10 名。</p><table tabindex="0"><thead><tr><th>操作</th><th>房主</th><th>房管</th><th>观众</th></tr></thead><tbody><tr><td>切换 / 删除影片</td><td>✅</td><td>✅</td><td>❌</td></tr><tr><td>踢出观众</td><td>✅</td><td>✅</td><td>❌</td></tr><tr><td>禁言观众</td><td>✅</td><td>✅</td><td>❌</td></tr><tr><td>语音禁言 / 移出语音</td><td>✅</td><td>✅</td><td>❌</td></tr><tr><td>任命 / 撤销房管</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>转交房主、修改房间设置</td><td>✅</td><td>❌</td><td>❌</td></tr></tbody></table><blockquote><p>房管<strong>不可操作</strong>房主、其他房管与管理员（root/admin）角色用户；<code>root</code> 账号在房间内受保护，无法被禁言或踢出。</p></blockquote><h2 id="五、屏幕标注" tabindex="-1">五、屏幕标注 <a class="header-anchor" href="#五、屏幕标注" aria-label="Permalink to &quot;五、屏幕标注&quot;">​</a></h2><p>在屏幕共享模式下，房主可以使用画笔工具在画面上圈画重点，所有观众实时看到。</p><h2 id="六、播放状态同步" tabindex="-1">六、播放状态同步 <a class="header-anchor" href="#六、播放状态同步" aria-label="Permalink to &quot;六、播放状态同步&quot;">​</a></h2><p>作为观众加入房间后，一切自动同步：</p><ul><li>房主播放/暂停/跳转/倍速 → 你自动跟随</li><li>房主断线后服务器接管广播，观看不中断</li><li>房主离线超 10 分钟房间自动关闭</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="语音听不到声音" tabindex="-1">语音听不到声音？ <a class="header-anchor" href="#语音听不到声音" aria-label="Permalink to &quot;语音听不到声音？&quot;">​</a></h3><p>确认房主已开启语音，检查扬声器，检查麦克风权限，尝试 HTTPS 访问。</p><h3 id="发送的申请房主没反应" tabindex="-1">发送的申请房主没反应？ <a class="header-anchor" href="#发送的申请房主没反应" aria-label="Permalink to &quot;发送的申请房主没反应？&quot;">​</a></h3><p>房主可能不在，稍等片刻。如果开启了自动通过，申请会自动生效。</p><h3 id="如何任命房管" tabindex="-1">如何任命房管？ <a class="header-anchor" href="#如何任命房管" aria-label="Permalink to &quot;如何任命房管？&quot;">​</a></h3><p>房主在<strong>观众管理</strong>面板中，点击目标用户旁边的盾牌图标即可任命或撤销房管。仅房主可操作，且只能任命已登录用户。</p><h3 id="被语音禁言了还能听到别人说话吗" tabindex="-1">被语音禁言了还能听到别人说话吗？ <a class="header-anchor" href="#被语音禁言了还能听到别人说话吗" aria-label="Permalink to &quot;被语音禁言了还能听到别人说话吗？&quot;">​</a></h3><p>可以。语音禁言只禁止你发言（服务器中转层直接丢弃你的音频包），收听不受影响。</p>',40)])])}const p=a(l,[["render",i]]);export{b as __pageData,p as default};
